 "content": "from collections import Counter, defaultdict, deque


def transform(grid):
    """Connect matching non-background tile centers through blank gaps."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0]) if grid else 0
    seen = set()
    centers = []

    # Each repeated tile has a same-colored rectangular frame, isolated by
    # blank cells. Find its component, then read the enclosed core color.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            top = min(y for y, _ in cells)
            bottom = max(y for y, _ in cells)
            left = min(x for _, x in cells)
            right = max(x for _, x in cells)
            if bottom - top < 2 or right - left < 2:
                continue
            cellset = set(cells)
            # A complete frame component must cover its full bounding-box edge.
            if not all((top, x) in cellset and (bottom, x) in cellset
                       for x in range(left, right + 1)):
                continue
            if not all((y, left) in cellset and (y, right) in cellset
                       for y in range(top, bottom + 1)):
                continue
            core = [grid[y][x]
                    for y in range(top + 1, bottom)
                    for x in range(left + 1, right)
                    if grid[y][x] != 0]
            if not core:
                continue
            core_color = Counter(core).most_common(1)[0][0]
            centers.append((top + (bottom - top) // 2,
                            left + (right - left) // 2,
                            core_color))

    if not centers:
        return out
    background = Counter(color for _, _, color in centers).most_common(1)[0][0]
    by_color = defaultdict(list)
    for r, c, color in centers:
        if color != background:
            by_color[color].append((r, c))

    # Join aligned matching centers. Only blank cells are drawn over, so the
    # intervening framed tiles remain unchanged.
    for color, points in by_color.items():
        rows = defaultdict(list)
        cols = defaultdict(list)
        for r, c in points:
            rows[r].append(c)
            cols[c].append(r)
        for r, columns in rows.items():
            columns.sort()
            if len(columns) > 1:
                lo, hi = columns[0], columns[-1]
                for c in range(lo + 1, hi):
                    if grid[r][c] == 0:
                        out[r][c] = color
        for c, row_indices in cols.items():
            row_indices.sort()
            if len(row_indices) > 1:
                lo, hi = row_indices[0], row_indices[-1]
                for r in range(lo + 1, hi):
                    if grid[r][c] == 0:
                        out[r][c] = color
    return out
