 "content": "from collections import Counter, defaultdict, deque


def transform(grid):
    """Connect aligned, equally colored tile interiors through separator gaps."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0]) if grid else 0
    seen = set()
    tiles = []

    # A tile is a solid rectangular frame component enclosing a uniform core.
    for r in range(h):
        for c in range(w):
            border = grid[r][c]
            if border == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == border):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            top = min(y for y, _ in cells)
            bottom = max(y for y, _ in cells)
            left = min(x for _, x in cells)
            right = max(x for _, x in cells)
            if bottom - top < 2 or right - left < 2:
                continue
            cellset = set(cells)
            if not all((top, x) in cellset and (bottom, x) in cellset
                       for x in range(left, right + 1)):
                continue
            if not all((y, left) in cellset and (y, right) in cellset
                       for y in range(top, bottom + 1)):
                continue
            core = [grid[y][x]
                    for y in range(top + 1, bottom)
                    for x in range(left + 1, right)
                    if grid[y][x] != 0]
            if not core:
                continue
            color = Counter(core).most_common(1)[0][0]
            tiles.append((top, bottom, left, right, color))

    if not tiles:
        return out
    background = Counter(tile[4] for tile in tiles).most_common(1)[0][0]
    groups_by_row = defaultdict(list)
    groups_by_col = defaultdict(list)
    for top, bottom, left, right, color in tiles:
        if color == background:
            continue
        groups_by_row[(top + bottom) // 2, color].append(
            (left, right, top + 1, bottom - 1))
        groups_by_col[(left + right) // 2, color].append(
            (top, bottom, left + 1, right - 1))

    # Each matched pair is joined only in the empty separator cells. The full
    # overlapping width/height of the inner motif is carried across the gaps.
    for (_, color), row_tiles in groups_by_row.items():
        row_tiles.sort()
        for first, second in zip(row_tiles, row_tiles[1:]):
            _, first_right, first_top, first_bottom = first
            second_left, _, second_top, second_bottom = second
            y0, y1 = max(first_top, second_top), min(first_bottom, second_bottom)
            for y in range(y0, y1 + 1):
                for x in range(first_right + 1, second_left):
                    if grid[y][x] == 0:
                        out[y][x] = color

    for (_, color), col_tiles in groups_by_col.items():
        col_tiles.sort()
        for first, second in zip(col_tiles, col_tiles[1:]):
            _, first_bottom, first_left, first_right = first
            second_top, _, second_left, second_right = second
            x0, x1 = max(first_left, second_left), min(first_right, second_right)
            for x in range(x0, x1 + 1):
                for y in range(first_bottom + 1, second_top):
                    if grid[y][x] == 0:
                        out[y][x] = color
    return out
