def transform(grid):
    """Connect repeated non-dominant tile cores along aligned rows/columns."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0]) if grid else 0
    seen = set()
    tiles = []

    # Find monochrome rectangular frames and read the enclosed motif color.
    for r in range(h):
        for c in range(w):
            border = grid[r][c]
            if border == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == border):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            top = min(y for y, _ in cells)
            bottom = max(y for y, _ in cells)
            left = min(x for _, x in cells)
            right = max(x for _, x in cells)
            if bottom - top < 2 or right - left < 2:
                continue
            cellset = set(cells)
            clipped_bottom = bottom == h - 1
            clipped_right = right == w - 1
            if not all((top, x) in cellset and
                       (clipped_bottom or (bottom, x) in cellset)
                       for x in range(left, right + 1)):
                continue
            if not all((y, left) in cellset and
                       (clipped_right or (y, right) in cellset)
                       for y in range(top, bottom + 1)):
                continue
            core_bottom = bottom if clipped_bottom else bottom - 1
            core_right = right if clipped_right else right - 1
            core = [grid[y][x]
                    for y in range(top + 1, core_bottom + 1)
                    for x in range(left + 1, core_right + 1)
                    if grid[y][x] != 0]
            if not core:
                continue
            color = Counter(core).most_common(1)[0][0]
            tiles.append((top, bottom, left, right, color))

    if not tiles:
        return out
    dominant = Counter(tile[4] for tile in tiles).most_common(1)[0][0]
    row_groups = defaultdict(list)
    col_groups = defaultdict(list)
    for top, bottom, left, right, color in tiles:
        if color == dominant:
            continue
        core_top = top + 1
        core_bottom = bottom if bottom == h - 1 else bottom - 1
        core_left = left + 1
        core_right = right if right == w - 1 else right - 1
        row_groups[( (top + bottom) // 2, color )].append(
            (left, right, core_top, core_bottom))
        col_groups[( (left + right) // 2, color )].append(
            (top, bottom, core_left, core_right))

    # Connect each aligned pair, preserving the framed tiles between them.
    for (_, color), group in row_groups.items():
        group.sort()
        for i, first in enumerate(group):
            for second in group[i + 1:]:
                _, right1, top1, bottom1 = first
                left2, _, top2, bottom2 = second
                y0, y1 = max(top1, top2), min(bottom1, bottom2)
                for y in range(y0, y1 + 1):
                    for x in range(right1 + 1, left2):
                        if grid[y][x] == 0:
                            out[y][x] = color
    for (_, color), group in col_groups.items():
        group.sort()
        for i, first in enumerate(group):
            for second in group[i + 1:]:
                _, bottom1, left1, right1 = first
                top2, _, left2, right2 = second
                x0, x1 = max(left1, left2), min(right1, right2)
                for x in range(x0, x1 + 1):
                    for y in range(bottom1 + 1, top2):
                        if grid[y][x] == 0:
                            out[y][x] = color
    return out
