 "content": "from collections import Counter, defaultdict, deque


def transform(grid):
    """Extend repeated minority-colored cores across aligned frame gaps."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0]) if grid else 0
    seen = set()
    tiles = []

    # Locate same-colored rectangular frames and identify their inner colors.
    for r in range(h):
        for c in range(w):
            border = grid[r][c]
            if border == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == border):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            top, bottom = min(y for y, _ in cells), max(y for y, _ in cells)
            left, right = min(x for _, x in cells), max(x for _, x in cells)
            if bottom - top < 2 or right - left < 2:
                continue
            cellset = set(cells)
            clipped_bottom, clipped_right = bottom == h - 1, right == w - 1
            if not all((top, x) in cellset and
                       (clipped_bottom or (bottom, x) in cellset)
                       for x in range(left, right + 1)):
                continue
            if not all((y, left) in cellset and
                       (clipped_right or (y, right) in cellset)
                       for y in range(top, bottom + 1)):
                continue
            core_bottom = bottom if clipped_bottom else bottom - 1
            core_right = right if clipped_right else right - 1
            core = [grid[y][x]
                    for y in range(top + 1, core_bottom + 1)
                    for x in range(left + 1, core_right + 1)
                    if grid[y][x] != 0]
            if core:
                tiles.append((top, bottom, left, right,
                              Counter(core).most_common(1)[0][0]))

    if not tiles:
        return out
    # Filter smaller same-color subcomponents that arise inside larger frames.
    sizes = Counter((b-t+1, r-l+1) for t, b, l, r, _ in tiles)
    common_size = sizes.most_common(1)[0][0]
    tiles = [tile for tile in tiles if (tile[1]-tile[0]+1,
                                       tile[3]-tile[2]+1) == common_size]

    row_groups, col_groups = defaultdict(list), defaultdict(list)
    for top, bottom, left, right, color in tiles:
        core_top = top + 1
        core_bottom = bottom if bottom == h - 1 else bottom - 1
        core_left = left + 1
        core_right = right if right == w - 1 else right - 1
        row_groups[((top + bottom) // 2, color)].append(
            (left, right, core_top, core_bottom))
        col_groups[((left + right) // 2, color)].append(
            (top, bottom, core_left, core_right))

    # In a row/column, only a strict-majority color is the ordinary motif;
    # connect all other repeated colors between consecutive occurrences.
    for center_r in {key[0] for key in row_groups}:
        counts = Counter(color for (r, color), items in row_groups.items()
                         if r == center_r for _ in items)
        total = sum(counts.values())
        if not counts or counts.most_common(1)[0][1] * 2 <= total:
            continue
        dominant = counts.most_common(1)[0][0]
        for color in counts:
            if color == dominant:
                continue
            group = sorted((tile for (r, c), items in row_groups.items()
                            if r == center_r and c == color for tile in items))
            for first, second in zip(group, group[1:]):
                _, right1, top1, bottom1 = first
                left2, _, top2, bottom2 = second
                for y in range(max(top1, top2), min(bottom1, bottom2) + 1):
                    for x in range(right1 + 1, left2):
                        if grid[y][x] == 0:
                            out[y][x] = color

    for center_c in {key[0] for key in col_groups}:
        counts = Counter(color for (c, color), items in col_groups.items()
                         if c == center_c for _ in items)
        total = sum(counts.values())
        if not counts or counts.most_common(1)[0][1] * 2 <= total:
            continue
        dominant = counts.most_common(1)[0][0]
        for color in counts:
            if color == dominant:
                continue
            group = sorted((tile for (c, v), items in col_groups.items()
                            if c == center_c and v == color for tile in items))
            for first, second in zip(group, group[1:]):
                _, bottom1, left1, right1 = first
                top2, _, left2, right2 = second
                for x in range(max(left1, left2), min(right1, right2) + 1):
                    for y in range(bottom1 + 1, top2):
                        if grid[y][x] == 0:
                            out[y][x] = color
    return out
